CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY, name TEXT, rev BIGINT NOT NULL DEFAULT 0, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, username TEXT NOT NULL, display TEXT, role TEXT NOT NULL, pw_hash TEXT, active INTEGER NOT NULL DEFAULT 1, must_change INTEGER NOT NULL DEFAULT 1, created_at BIGINT NOT NULL, last_login BIGINT, pw_changed_at BIGINT, UNIQUE(tenant_id, username));
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL, tenant_id TEXT NOT NULL, csrf TEXT NOT NULL, created_at BIGINT NOT NULL, last_seen BIGINT NOT NULL, expires_at BIGINT NOT NULL, ip TEXT, ua TEXT);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS login_attempts(k TEXT PRIMARY KEY, n INTEGER NOT NULL, first_at BIGINT NOT NULL, locked_until BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS records(tenant_id TEXT NOT NULL, coll TEXT NOT NULL, rid TEXT NOT NULL, kind TEXT NOT NULL, seq BIGINT NOT NULL, data TEXT NOT NULL, ver INTEGER NOT NULL, deleted INTEGER NOT NULL DEFAULT 0, rev BIGINT NOT NULL, updated_by TEXT, updated_at BIGINT NOT NULL, PRIMARY KEY(tenant_id, coll, rid));
CREATE INDEX IF NOT EXISTS records_rev ON records(tenant_id, rev);
CREATE TABLE IF NOT EXISTS history(id INTEGER PRIMARY KEY AUTOINCREMENT, tenant_id TEXT NOT NULL, coll TEXT NOT NULL, rid TEXT NOT NULL, ver INTEGER NOT NULL, op TEXT NOT NULL, data TEXT, by_user TEXT, ts BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS history_rec ON history(tenant_id, coll, rid);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT, ts BIGINT NOT NULL, tenant_id TEXT NOT NULL, user_name TEXT, action TEXT NOT NULL, detail TEXT, ip TEXT);
CREATE INDEX IF NOT EXISTS audit_ts ON audit_log(tenant_id, ts);
CREATE TABLE IF NOT EXISTS sequences(tenant_id TEXT NOT NULL, prefix TEXT NOT NULL, n BIGINT NOT NULL, PRIMARY KEY(tenant_id, prefix));
CREATE TABLE IF NOT EXISTS roles(tenant_id TEXT NOT NULL, name TEXT NOT NULL, write_rules TEXT NOT NULL, hr_access INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(tenant_id, name));
CREATE TABLE IF NOT EXISTS staff_pins(tenant_id TEXT NOT NULL, staff_id TEXT NOT NULL, pin_hash TEXT NOT NULL, legacy INTEGER NOT NULL DEFAULT 0, fails INTEGER NOT NULL DEFAULT 0, locked_until BIGINT NOT NULL DEFAULT 0, updated_at BIGINT NOT NULL, PRIMARY KEY(tenant_id, staff_id));
CREATE TABLE IF NOT EXISTS platform_packages(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, price INTEGER NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'KES', cycle TEXT NOT NULL DEFAULT 'monthly', modules TEXT NOT NULL DEFAULT '[]', max_users INTEGER NOT NULL DEFAULT 0, trial_days INTEGER NOT NULL DEFAULT 30, active INTEGER NOT NULL DEFAULT 1, sort INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS platform_clients(tenant_id TEXT PRIMARY KEY, name TEXT, package_id TEXT, add_modules TEXT NOT NULL DEFAULT '[]', remove_modules TEXT NOT NULL DEFAULT '[]', max_users INTEGER, price INTEGER, status TEXT NOT NULL DEFAULT 'trial', paid_until TEXT, contact TEXT, phone TEXT, email TEXT, country TEXT, notes TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tenant_hosts(host TEXT PRIMARY KEY, tenant_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS platform_payments(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, amount INTEGER NOT NULL, currency TEXT NOT NULL, method TEXT, ref TEXT, package_id TEXT, period_from TEXT, period_to TEXT, note TEXT, by_user TEXT, paid_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS platform_pay_t ON platform_payments(tenant_id, paid_at);
